package com.npcdialogue;

import net.runelite.client.config.*;

import java.awt.*;

@ConfigGroup(DialogueConfig.CONFIG_GROUP)
public interface DialogueConfig extends Config {
    String CONFIG_GROUP = "visualnpcdialogue";

    @ConfigItem(
        keyName = "disableDialogueDuringCutscene",
        name = "Disable during cutscenes",
        description = "Disable chatbox and overhead dialogue during cutscenes",
        position = 1
    )
    default boolean disableDialogueDuringCutscene() {
        return true;
    }

    @ConfigSection(
            name = "Ignore List",
            description = "Custom exclusion list",
            position = 100,
            closedByDefault = true
    )
    String SECTION_IGNORE_LIST = "ignoreList";

    @ConfigItem(
        keyName = "ignoredNPCs",
        name = "Ignored NPCs",
        description = "List of ignored NPCs, separated by commas",
        position = 101,
        section = SECTION_IGNORE_LIST
    )
    default String ignoredNPCs() {
        return "";
    }

    @ConfigSection(
            name = "Chatbox Dialogue",
            description = "All options for displaying dialogue in the chatbox",
            position = 200
    )
    String SECTION_CHAT = "chatDialogue";

    @ConfigItem(
            keyName = "displayChatboxNpcDialogue",
            name = "NPC Chatbox Dialogue",
            description = "Display NPC dialogue in the chatbox",
            section = SECTION_CHAT,
            position = 201
    )
    default boolean displayChatboxNpcDialogue() {
        return true;
    }

    @ConfigItem(
            keyName = "displayChatboxPlayerDialogue",
            name = "Player Chatbox Dialogue",
            description = "Display player dialogue in the chatbox",
            section = SECTION_CHAT,
            position = 202
    )
    default boolean displayChatboxPlayerDialogue() {
        return true;
    }

    @Alpha
    @ConfigItem(
            keyName = "nameColor",
            name = "Chatbox Name Color",
            description = "Select the display color for the name in the chatbox",
            section = SECTION_CHAT,
            position = 203
    )
    default Color nameColor() {
        return Color.BLACK;
    }

    @Alpha
    @ConfigItem(
            keyName = "contentColor",
            name = "Chatbox Text Color",
            description = "Select the display color for the message text in the chatbox",
            section = SECTION_CHAT,
            position = 204
    )
    default Color contentColor() {
        return Color.BLUE;
    }

    @ConfigSection(
            name = "Overhead Dialogue",
            description = "All options for displaying overhead dialogue",
            position = 300
    )
    String SECTION_OVERHEAD = "overheadDialogue";

    @ConfigItem(
            keyName = "displayOverheadNpcDialogue",
            name = "NPC Overhead Dialogue",
            description = "Display dialogue above the NPC",
            section = SECTION_OVERHEAD,
            position = 301
    )
    default boolean displayOverheadNpcDialogue() {
        return true;
    }

    @ConfigItem(
            keyName = "displayOverheadPlayerDialogue",
            name = "Player Overhead Dialogue",
            description = "Display player dialogue overhead",
            section = SECTION_OVERHEAD,
            position = 302
    )
    default boolean displayOverheadPlayerDialogue() {
        return true;
    }

    @ConfigItem(
        keyName = "durationOverheadText",
        name = "Overhead Duration",
        description = "How long overhead text lasts. 30 cycles = 1 game tick (~0.6s).<br>Default: 100 (~3.3 ticks)",
        section = SECTION_OVERHEAD,
        position = 303
    )
    default int durationOverheadText() {
        return 100;
    }

    @ConfigItem(
        keyName = "truncateOverheadText",
        name = "Truncate Overhead",
        description = "Truncate overhead text after X characters<br>Set to 0 to disable",
        section = SECTION_OVERHEAD,
        position = 304
    )
    default int truncateOverheadText() {
        return 0;
    }
}

package com.npcdialogue;

import com.google.inject.Provides;
import com.npcdialogue.model.Dialogue;
import com.npcdialogue.service.ChatboxService;
import com.npcdialogue.service.OverheadService;
import com.npcdialogue.util.DialogueUtils;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Text;

import javax.inject.Inject;

import static net.runelite.api.gameval.VarbitID.CUTSCENE_STATUS;

@Slf4j
@PluginDescriptor(
    name = "Visual NPC Dialogue",
    description = "Adds dialogue to the chatbox and above NPCs heads",
    tags = { "npc", "dialogue", "chat" }
)
public class DialoguePlugin extends Plugin {
    private static final int SCRIPT_CHAT_DIALOGUE = 600;

    @Inject private Client client;
    @Inject private DialogueConfig config;
    @Inject private ChatboxService chatboxService;
    @Inject private OverheadService overheadService;

    private NPC lastInteractedActor = null;

    @Provides
    DialogueConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(DialogueConfig.class);
    }

    /**
     * Looks at current dialogue and stores it if valid
     * @param dialogue Dialogue to process and display
     */
    private void processDialogue(Dialogue dialogue) {
        if (DialogueUtils.isIgnoredActor(config.ignoredNPCs(), dialogue.getName())) {
            return;
        }
        displayDialogue(dialogue);
    }

    private void displayDialogue(Dialogue dialogue) {
        if (dialogue.getType() == Dialogue.Type.PLAYER) {
            if (config.displayChatboxPlayerDialogue()) {
                chatboxService.addDialogMessage(dialogue);
            }
            if (config.displayOverheadPlayerDialogue()) {
                overheadService.setOverheadTextPlayer(dialogue);
            }
        }

        if (dialogue.getType() == Dialogue.Type.NPC) {
            if (config.displayChatboxNpcDialogue()) {
                chatboxService.addDialogMessage(dialogue);
            }
            if (config.displayOverheadNpcDialogue()) {
                Actor actor = findActor(dialogue.getName());
                if (actor == null) {
                    log.debug("No valid actor found for NPC overhead dialogue, skipping overhead");
                    return;
                }
                overheadService.setOverheadTextNpc(actor, dialogue);
            }
        }
    }

    /**
     * Finds actor based on NPC name. To be used when dialogue is not started by interaction
     * @return The found actor or the last interacted actor
     */
    private Actor findActor(String name) {
        if (lastInteractedActor != null && name.equals(lastInteractedActor.getName())) {
            return lastInteractedActor;
        }

        for (NPC npc : client.getTopLevelWorldView().npcs()) {
            if (name.equals(npc.getName())) {
                return npc;
            }
        }

        if (lastInteractedActor != null && lastInteractedActor.getId() != -1) {
            log.debug("Unable to find matching actor. Fallback to using lastInteractedActor: {} ({})", lastInteractedActor.getName(), lastInteractedActor.getId());
            return lastInteractedActor;
        }
        return null;
    }

    @Subscribe
    public void onScriptPostFired(ScriptPostFired event) {
        if (event.getScriptId() != SCRIPT_CHAT_DIALOGUE) return;
        if (config.disableDialogueDuringCutscene() && client.getVarbitValue(CUTSCENE_STATUS) == 1) return;

        Widget text;
        Widget name;

        if (client.getWidget(InterfaceID.ChatLeft.UNIVERSE) != null) {
            // NPC
            text = client.getWidget(InterfaceID.ChatLeft.TEXT);
            name = client.getWidget(InterfaceID.ChatLeft.NAME);
        } else if (client.getWidget(InterfaceID.ChatRight.UNIVERSE) != null) {
            // PLAYER
            text = client.getWidget(InterfaceID.ChatRight.TEXT);
            name = client.getWidget(InterfaceID.ChatRight.NAME);
        } else {
            log.debug("Could not find dialogue widgets post script");
            return;
        }
        if (text == null || name == null) return;

        boolean isPlayer = name.getText().equals(client.getLocalPlayer().getName());

        processDialogue(new Dialogue(name.getText(), Text.sanitizeMultilineText(text.getText()), isPlayer ? Dialogue.Type.PLAYER : Dialogue.Type.NPC));
    }

    /**
     * Save NPCs the player interacts with to lastInteractedActor variable
     */
    @Subscribe
    public void onInteractingChanged(InteractingChanged event) {
        if (event.getTarget() == null || event.getSource() != client.getLocalPlayer()) {
            return;
        }

        lastInteractedActor = (NPC) event.getTarget();
        log.debug("Interacted with actor: {} ({})", lastInteractedActor.getName(), lastInteractedActor.getId());
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged gameStateChanged) {
        switch (gameStateChanged.getGameState()) {
            case CONNECTION_LOST:
            case HOPPING:
            case LOGIN_SCREEN:
                lastInteractedActor = null;
                break;
            default:
                break;
        }
    }
}

package com.npcdialogue.model;

import lombok.Data;

@Data
public class Dialogue {
    public enum Type { NPC, PLAYER }

    private final String name;
    private final String text;
    private final Type type;
}

package com.npcdialogue.service;

import com.npcdialogue.DialogueConfig;
import com.npcdialogue.model.Dialogue;
import com.npcdialogue.util.DialogueUtils;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;

import javax.inject.Inject;

@Slf4j
public class ChatboxService {
    @Inject private DialogueConfig config;
    @Inject private ChatMessageManager chatMessageManager;

    /**
     * Adds NPC/Player dialogue to chatbox
     */
    public void addDialogMessage(Dialogue dialogue) {
        final ChatMessageBuilder chatMessage = new ChatMessageBuilder()
                .append(config.nameColor(), DialogueUtils.trimName(dialogue.getName()))
                .append(config.nameColor(), ": ")
                .append(config.contentColor(), dialogue.getText());

        chatMessageManager.queue(QueuedMessage.builder()
                .type(ChatMessageType.CONSOLE)
                .runeLiteFormattedMessage(chatMessage.build())
                .build());

        log.debug("Chatbox dialogue built and queued: {}", dialogue);
    }
}

package com.npcdialogue.service;

import com.npcdialogue.DialogueConfig;
import com.npcdialogue.model.Dialogue;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;

import javax.inject.Inject;

@Slf4j
public class OverheadService {
    @Inject private Client client;
    @Inject private DialogueConfig config;

    public void setOverheadTextNpc(Actor npc, Dialogue dialogue) {
        npc.setOverheadText(truncate(dialogue.getText()));
        npc.setOverheadCycle(config.durationOverheadText());
        log.debug("Set overhead dialogue for {} to: {}", npc.getName(), dialogue.getText());
    }

    public void setOverheadTextPlayer(Dialogue dialogue) {
        Actor player = client.getLocalPlayer();
        player.setOverheadText(truncate(dialogue.getText()));
        player.setOverheadCycle(config.durationOverheadText());
        log.debug("Set overhead dialogue for player to: {}", dialogue.getText());
    }

    private String truncate(String text) {
        int maxLength = config.truncateOverheadText();

        if (maxLength <= 0 || text == null || text.length() <= maxLength) {
            return text;
        } else if (maxLength <= 3) {
            return text.substring(0, maxLength);
        }

        return text.substring(0, maxLength - 3) + "...";
    }
}

package com.npcdialogue.util;

import lombok.extern.slf4j.Slf4j;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j
public class DialogueUtils {
    // Regex pattern to match parentheses and their contents at the end of the string
    private static final Pattern SUFFIX_PATTERN = Pattern.compile("\\s*\\([^)]*\\)\\s*$");

    /**
     * Remove suffixes from NPC names
     * @param name NPC name
     * @return name without suffixes
     * @see <a href="https://oldschool.runescape.wiki/w/Suffixes">Wiki: Suffixes</a>
     */
    public static String trimName(String name) {
        return SUFFIX_PATTERN.matcher(name).replaceAll("").trim();
    }

    /**
     * Check if actor is listed in the NPC ignore list
     * @param name The NPC name to check
     * @return Whether actor is in the ignore list
     */
    public static boolean isIgnoredActor(String ignoreList, String name) {
        if (name == null || ignoreList == null) {
            return false;
        }
        // Loop through Ignore List and look for NPC name
        String[] names = ignoreList.split(",");
        String trimmedName = trimName(name);
        for (String n : names) {
            String ignored = n.trim();
            if (ignored.equalsIgnoreCase(name) || ignored.equalsIgnoreCase(trimmedName)) {
                log.debug("NPC found in ignore list: {}", name);
                return true;
            }
        }
        return false;
    }
}

